// Все настройки прототипа. Меняй числа, сохраняй файл и обновляй страницу (F5).
// Единицы: метры и секунды. Метры условные, это масштаб мира, а не реальные размеры.
// ВРЕМЕННО: все числа ниже стартовые, подобраны для первой проверки.

const CONFIG = {

  // ---------- Падение и наклон ----------

  // Сила падения вниз, м/с².
  // Больше: шар быстрее разгоняется и на обход остаётся меньше времени.
  fallGravity: 2,

  // Скорость шара вбок при полном наклоне, м/с.
  // Наклон задаёт скорость напрямую: вернул телефон — шар перестал смещаться.
  // Больше: шар быстрее пересекает трубу, но точнее целиться сложнее.
  sideMaxSpeed: 4.5,

  // Как быстро шар набирает и гасит боковую скорость, м/с².
  // Больше: шар слушается мгновенно, аркаднее.
  // Меньше: появляется инерция, и шар надо ловить встречным наклоном.
  sideResponse: 40,

  // Скорость отклика клавиатуры: сколько полных наклонов в секунду, 1/с.
  // Больше: наклон с клавиш включается и отпускается резче.
  // Меньше: движение плавнее, но реакция запаздывает.
  keyboardTiltRate: 6,


  // ---------- Датчик телефона ----------

  // Угол поворота телефона, при котором наклон считается полным, градусы.
  // Меньше: шар отзывчивее, хватает маленького движения кистью.
  // Больше: управление точнее, но поворачивать телефон надо сильнее.
  sensorFullTiltAngle: 18,

  // Мёртвая зона: повороты меньше этого угла игнорируются, градусы.
  // Больше: дрожание рук не двигает шар, но отклик на малый наклон пропадает.
  // 0: мёртвой зоны нет.
  sensorDeadZoneAngle: 4,

  // Как быстро шар реагирует на поворот телефона: полных наклонов в секунду, 1/с.
  // Больше: реакция быстрее, но заметнее дрожание рук.
  // Меньше: движение плавнее, но с запаздыванием.
  sensorTiltRate: 12,

  // Если шар уходит не в ту сторону, поставь true.
  sensorInvert: false,


  // ---------- Плоский телефон ----------

  // Игра встаёт на паузу, если телефон наклонён к горизонту меньше этого угла, градусы.
  // 0 — лежит плашмя, 90 — стоит вертикально.
  // Больше: пауза срабатывает раньше и может мешать, если играть, глядя на телефон сверху.
  flatEnterAngle: 15,

  // Игра продолжается, когда телефон поднят выше этого угла, градусы.
  // Должен быть больше flatEnterAngle, иначе пауза будет мигать на границе.
  flatExitAngle: 25,

  // Сколько секунд телефон должен лежать, чтобы включилась пауза, с.
  // Больше: случайные рывки не вызывают паузу, но она срабатывает позже.
  flatHoldTime: 0.3,


  // ---------- Переворот и откат ----------

  // Угол телефона, с которого шар начинает останавливаться, градусы.
  // 0 — телефон вертикально, 90 — горизонтально, 180 — вверх ногами.
  // Меньше: остановка наступает раньше, для обычного наклона остаётся меньше места.
  flipStopStartAngle: 70,

  // Угол телефона, с которого начинается откат вверх, градусы.
  // Больше: телефон надо перевернуть сильнее, случайный откат менее вероятен.
  flipRollbackAngle: 110,

  // Инерция при перевороте: с какой силой шар гасит скорость, м/с².
  // Чем быстрее летел шар, тем дольше он катится дальше по инерции.
  // Меньше: инерция сильнее, шар дольше не останавливается.
  // Больше: шар тормозит резче. Тем же торможением шар замирает в конце отката.
  flipBrakeForce: 8,

  // Сила отката относительно силы падения, от 0 до 1.
  // 1: откат разгоняется как падение. Меньше: откат медленнее.
  rollbackGravityRatio: 0.8,

  // Расстояние одного отката от точки его начала, м.
  // Больше: за один откат можно подняться выше и сильнее разогнаться потом.
  rollbackDistance: 8,

  // Скорость поворота виртуального телефона на клавиатуре, градусов в секунду.
  // Больше: пробел переворачивает быстрее и шар проскакивает зону остановки быстрее.
  keyboardFlipSpeed: 500,


  // ---------- Защита физики ----------

  // Защитный потолок скорости, м/с. Это не игровой параметр.
  // Нужен, чтобы физика не ломалась. Выше 100 ставить не стоит:
  // движок ограничивает путь за один шаг.
  safetyMaxSpeed: 60,


  // ---------- Шар ----------

  // Радиус шара, м.
  // Больше: шар заметнее, но обойти препятствия труднее.
  ballRadius: 0.26,

  // Плотность шара, кг/м². На падение почти не влияет, важна для столкновений.
  ballDensity: 1,

  // Упругость шара, от 0 до 1.
  // 0: удар без отскока. 1: отскок почти без потери скорости.
  ballRestitution: 0.3,

  // Трение шара о предметы, от 0 до 1.
  // Больше: при касании стенки шар сильнее закручивается и теряет больше скорости.
  ballFriction: 0.3,


  // ---------- Труба ----------

  // Ширина трубы внутри, м.
  // Меньше: сложнее, это главный рычаг сложности.
  pipeWidth: 3,

  // Длина трубы от верха до низа, м.
  // Больше: дольше падение и выше скорость в конце.
  pipeLength: 40,

  // Ветки. side: "left" или "right" — из какой стенки торчит.
  // depth: глубина от верха трубы, м. length: насколько торчит внутрь, м.
  // thickness: толщина, м. Можно добавлять и удалять строки.
  branches: [
    { side: "left",  depth: 10, length: 0.9, thickness: 0.12 },
    { side: "right", depth: 20, length: 0.9, thickness: 0.12 },
  ],


  // ---------- Камера и вид ----------

  // Сколько метров мира видно по ширине экрана.
  // Больше: камера дальше, всё мельче, но труба видна с запасом по бокам.
  viewWidth: 3.6,

  // Где держать шар по высоте экрана: 0 — верх, 1 — низ.
  // Меньше: шар выше и препятствия видны раньше.
  cameraBallPosition: 0.3,

  // Шаг поперечных меток на стенках, м. Без них в прямой трубе не видно движения.
  // Меньше: ощущение скорости сильнее.
  tickSpacing: 1,
};
